        let (t5, t6) = t3.addingReportingOverflow(t2)
        let t7: UInt64 = (t4 ? 1 : 0) &+ (t6 ? 1 : 0)
        let (t8, t9) = a.l2.addingReportingOverflow(b.l2)
        let (t10, t11) = t8.addingReportingOverflow(t7)
        let t12: UInt64 = (t9 ? 1 : 0) &+ (t11 ? 1 : 0)
        let (t13, t14) = a.l3.addingReportingOverflow(b.l3)
        let (t15, t16) = t13.addingReportingOverflow(t12)
        let t17: UInt64 = (t14 ? 1 : 0) &+ (t16 ? 1 : 0)
        let (t18, t19) = t0.addingReportingOverflow(0x1_0000_03D1)
        let t20: UInt64 = t19 ? 1 : 0
        let (t21, t22) = t5.addingReportingOverflow(0)
        let (t23, t24) = t21.addingReportingOverflow(t20)
        let t25: UInt64 = (t22 ? 1 : 0) &+ (t24 ? 1 : 0)
        let (t26, t27) = t10.addingReportingOverflow(0)
        let (t28, t29) = t26.addingReportingOverflow(t25)
        let t30: UInt64 = (t27 ? 1 : 0) &+ (t29 ? 1 : 0)
        let (t31, t32) = t15.addingReportingOverflow(0)
        let (t33, t34) = t31.addingReportingOverflow(t30)
        let t35: UInt64 = (t32 ? 1 : 0) &+ (t34 ? 1 : 0)
        let t36 = t17 | t35
        let t37 = (t18 & (0 &- t36)) | (t0 & ~(0 &- t36))
        let t38 = (t23 & (0 &- t36)) | (t5 & ~(0 &- t36))
        let t39 = (t28 & (0 &- t36)) | (t10 & ~(0 &- t36))
        let t40 = (t33 & (0 &- t36)) | (t15 & ~(0 &- t36))
        return Integer256(l0: t37, l1: t38, l2: t39, l3: t40)
    }

    /// a − b mod p for a, b < p (`Field.subMod_spec`).
    static func subtract(_ a: Integer256, _ b: Integer256) -> Integer256 {
        let (t0, t1) = a.l0.subtractingReportingOverflow(b.l0)
        let t2: UInt64 = t1 ? 1 : 0
        let (t3, t4) = a.l1.subtractingReportingOverflow(b.l1)
        let (t5, t6) = t3.subtractingReportingOverflow(t2)
        let t7: UInt64 = (t4 ? 1 : 0) &+ (t6 ? 1 : 0)
        let (t8, t9) = a.l2.subtractingReportingOverflow(b.l2)
        let (t10, t11) = t8.subtractingReportingOverflow(t7)
        let t12: UInt64 = (t9 ? 1 : 0) &+ (t11 ? 1 : 0)
        let (t13, t14) = a.l3.subtractingReportingOverflow(b.l3)
        let (t15, t16) = t13.subtractingReportingOverflow(t12)
        let t17: UInt64 = (t14 ? 1 : 0) &+ (t16 ? 1 : 0)
        let t18 = (0xFFFF_FFFE_FFFF_FC2F & (0 &- t17)) | (0 & ~(0 &- t17))
        let t19 = (0xFFFF_FFFF_FFFF_FFFF & (0 &- t17)) | (0 & ~(0 &- t17))
        let (t20, t21) = t0.addingReportingOverflow(t18)
        let t22: UInt64 = t21 ? 1 : 0
        let (t23, t24) = t5.addingReportingOverflow(t19)
        let (t25, t26) = t23.addingReportingOverflow(t22)
        let t27: UInt64 = (t24 ? 1 : 0) &+ (t26 ? 1 : 0)
        let (t28, t29) = t10.addingReportingOverflow(t19)
        let (t30, t31) = t28.addingReportingOverflow(t27)
        let t32: UInt64 = (t29 ? 1 : 0) &+ (t31 ? 1 : 0)
        let (t33, _) = t15.addingReportingOverflow(t19)
        let (t35, _) = t33.addingReportingOverflow(t32)
        return Integer256(l0: t20, l1: t25, l2: t30, l3: t35)
    }

    /// −a mod p for a < p (`Field.negMod_spec`).
    static func negate(_ a: Integer256) -> Integer256 {
        let (t0, t1) = UInt64(0).subtractingReportingOverflow(a.l0)
        let t2: UInt64 = t1 ? 1 : 0
        let (t3, t4) = UInt64(0).subtractingReportingOverflow(a.l1)
        let (t5, t6) = t3.subtractingReportingOverflow(t2)
        let t7: UInt64 = (t4 ? 1 : 0) &+ (t6 ? 1 : 0)
        let (t8, t9) = UInt64(0).subtractingReportingOverflow(a.l2)
        let (t10, t11) = t8.subtractingReportingOverflow(t7)
        let t12: UInt64 = (t9 ? 1 : 0) &+ (t11 ? 1 : 0)
        let (t13, t14) = UInt64(0).subtractingReportingOverflow(a.l3)
        let (t15, t16) = t13.subtractingReportingOverflow(t12)
        let t17: UInt64 = (t14 ? 1 : 0) &+ (t16 ? 1 : 0)
        let t18 = (0xFFFF_FFFE_FFFF_FC2F & (0 &- t17)) | (0 & ~(0 &- t17))
        let t19 = (0xFFFF_FFFF_FFFF_FFFF & (0 &- t17)) | (0 & ~(0 &- t17))
        let (t20, t21) = t0.addingReportingOverflow(t18)
        let t22: UInt64 = t21 ? 1 : 0
        let (t23, t24) = t5.addingReportingOverflow(t19)
        let (t25, t26) = t23.addingReportingOverflow(t22)
        let t27: UInt64 = (t24 ? 1 : 0) &+ (t26 ? 1 : 0)
        let (t28, t29) = t10.addingReportingOverflow(t19)
        let (t30, t31) = t28.addingReportingOverflow(t27)
        let t32: UInt64 = (t29 ? 1 : 0) &+ (t31 ? 1 : 0)
        let (t33, _) = t15.addingReportingOverflow(t19)
        let (t35, _) = t33.addingReportingOverflow(t32)
        return Integer256(l0: t20, l1: t25, l2: t30, l3: t35)
    }

    /// Any 256-bit a modulo p (`Field.canonical_spec`).
    static func reduce(_ a: Integer256) -> Integer256 {
        let (t0, t1) = a.l0.addingReportingOverflow(0x1_0000_03D1)
        let t2: UInt64 = t1 ? 1 : 0
        let (t3, t4) = a.l1.addingReportingOverflow(0)
        let (t5, t6) = t3.addingReportingOverflow(t2)
        let t7: UInt64 = (t4 ? 1 : 0) &+ (t6 ? 1 : 0)
        let (t8, t9) = a.l2.addingReportingOverflow(0)
        let (t10, t11) = t8.addingReportingOverflow(t7)
        let t12: UInt64 = (t9 ? 1 : 0) &+ (t11 ? 1 : 0)
        let (t13, t14) = a.l3.addingReportingOverflow(0)
        let (t15, t16) = t13.addingReportingOverflow(t12)
        let t17: UInt64 = (t14 ? 1 : 0) &+ (t16 ? 1 : 0)
        let t18 = (t0 & (0 &- t17)) | (a.l0 & ~(0 &- t17))
        let t19 = (t5 & (0 &- t17)) | (a.l1 & ~(0 &- t17))
        let t20 = (t10 & (0 &- t17)) | (a.l2 & ~(0 &- t17))
        let t21 = (t15 & (0 &- t17)) | (a.l3 & ~(0 &- t17))
        return Integer256(l0: t18, l1: t19, l2: t20, l3: t21)
    }
}
